import { useEffect, useId, useRef, useState, type ReactNode } from 'react';
import { qs, repoPath, useApi, type ApiError, type RepoSearch } from './api';
import { fmtRange, num } from './format';
import { lastIncludedDay, nextDay, PRESETS, presetRange, toDateInput, type Coverage, type PresetKey, type Selection } from './range';
import { Link, navigate } from './router';

// A one-sentence explanation, shown on hover or keyboard focus.
export function Info({ text }: { text: string }) {
  const id = useId();
  return (
    <span className="info">
      <button type="button" className="info-btn" aria-describedby={id} aria-label="More information">i</button>
      <span role="tooltip" id={id} className="info-tip">{text}</span>
    </span>
  );
}

export function Card({ title, info, aside, children, className = '' }: {
  title: string; info?: string; aside?: ReactNode; children: ReactNode; className?: string;
}) {
  return (
    <section className={`card ${className}`}>
      <header className="card-head">
        <h2>{title}{info && <Info text={info} />}</h2>
        {aside}
      </header>
      {children}
    </section>
  );
}

export function Loading() {
  return <p className="status">Loading…</p>;
}

export function ErrorMessage({ error, onRetry }: { error: ApiError; onRetry?: () => void }) {
  return (
    <div className="status status-error" role="alert">
      <span>{error.message}</span>
      {onRetry && <button type="button" className="btn-link" onClick={onRetry}>Retry</button>}
    </div>
  );
}

export function Empty({ children }: { children: ReactNode }) {
  return <p className="status">{children}</p>;
}

// Renders loading / error / content for one API call. Holds stale content (dimmed)
// while a refetch is in flight.
export function Async<T>({ state, children }: {
  state: { data: T | null; error: ApiError | null; loading: boolean; reload: () => void };
  children: (data: T) => ReactNode;
}) {
  if (state.error) return <ErrorMessage error={state.error} onRetry={state.reload} />;
  if (!state.data) return <Loading />;
  return <div className={state.loading ? 'stale' : undefined} aria-busy={state.loading}>{children(state.data)}</div>;
}

export function RangeControls({ sel, cov, onChange }: {
  sel: Selection; cov: Coverage; onChange: (query: string) => void;
}) {
  const [custom, setCustom] = useState(sel.preset === null);
  const min = toDateInput(cov.start);
  const max = lastIncludedDay(cov.end);
  const start = toDateInput(sel.from);
  const end = lastIncludedDay(sel.to);

  const setCustomRange = (s: string, e: string) => {
    if (s && e && s <= e && s >= min && e <= max) onChange(`from=${s}&to=${nextDay(e)}`);
  };

  return (
    <div className="range">
