} from '../api';
import { Async, Card, Empty, ErrorMessage, Info, Loading } from '../components';
import { fmtDateTime, fmtDay, fmtDuration, fmtHour, NA, num } from '../format';
import type { Selection } from '../range';
import { Link } from '../router';

const SERIES_INFO: Record<Series, { label: string; info: string }> = {
  stars: { label: 'Stars', info: 'Star (WatchEvent) events.' },
  forks: { label: 'Forks', info: 'Fork events.' },
  prs_opened: { label: 'PRs opened', info: 'PRs by creation time, including ones seen only through comments.' },
  prs_merged: { label: 'PRs merged', info: 'PRs by merge time.' },
  issues: { label: 'Issues opened / closed', info: 'Issues opened, closed or reopened.' },
  reviews: { label: 'Reviews', info: 'PR reviews and review comments.' },
  comments: { label: 'Comments', info: 'Comments on issues, PRs and commits.' },
  pushes: { label: 'Pushes', info: 'Push events; the data has no per-push commit counts.' },
};

export function RepoDetailPage({ repo, sel, rangeQuery }: { repo: string; sel: Selection; rangeQuery: string }) {
  const base = `/api/repos/${repoPath(repo)}`;
  const range = { from: sel.from, to: sel.to };
  const activity = useApi<Activity>(`${base}/activity?${qs(range)}`);

  // Every panel 404s together for an unknown repo; show one page-level message.
  if (activity.error?.code === 'repo_not_found') {
    return (
      <div className="card">
        <ErrorMessage error={activity.error} />
        <p className="status"><Link href={`/?${rangeQuery}`}>Back to trending</Link></p>
      </div>
    );
  }

  return (
    <>
      <ActivityPanel state={activity} />
      <div className="grid-2">
        <MergePanel url={`${base}/pulls/merged?${qs({ ...range, limit: 1 })}`} />
        <ContributorsPanel base={base} range={range} />
      </div>
      <OpenPrsPanel base={base} repo={repo} />
    </>
  );
}

function ActivityPanel({ state }: { state: ReturnType<typeof useApi<Activity>> }) {
  return (
    <Card
      title="Activity over time"
      aside={state.data && <p className="card-note">{state.data.bucket === 'hour' ? 'Hourly' : 'Daily'} UTC buckets · each chart has its own scale</p>}
    >
      <Async state={state}>
        {(d) => (
          <div className="multiples">
            {SERIES.map((s) => <SeriesChart key={s} data={d} series={s} />)}
          </div>
        )}
      </Async>
    </Card>
  );
}

function SeriesChart({ data, series }: { data: Activity; series: Series }) {
  const { label, info } = SERIES_INFO[series];
  const max = Math.max(...data.buckets.map((b) => b[series]));
  const fmtTick = data.bucket === 'hour' ? fmtHour : fmtDay;
  const first = data.buckets[0]?.start;
  const last = data.buckets.at(-1)?.start;
  return (
    <figure className="multiple">
      <figcaption>
        <span className="multiple-label">{label}<Info text={info} /></span>
        <span className="multiple-total">{num(data.totals[series])}</span>
      </figcaption>
      <div className="multiple-plot">
        <ResponsiveContainer width="100%" height="100%">
          <BarChart data={data.buckets} margin={{ top: 4, right: 4, bottom: 0, left: 0 }} barCategoryGap="12%">
            <CartesianGrid vertical={false} stroke="var(--grid)" />
            <XAxis
              dataKey="start"
              ticks={first && last && first !== last ? [first, last] : first ? [first] : []}
              interval={0}
              tickFormatter={fmtTick}
              tick={{ fill: 'var(--muted)', fontSize: 11 }}
              tickLine={false}
              axisLine={{ stroke: 'var(--axis)' }}
              height={20}
            />
            <YAxis
              domain={[0, Math.max(max, 1)]}
              ticks={max > 0 ? [0, max] : [0]}
              allowDecimals={false}
              tickFormatter={(v: number) => num(v)}
              tick={{ fill: 'var(--muted)', fontSize: 11 }}
              tickLine={false}
              axisLine={false}
              width={34}
            />
            <Tooltip
              cursor={{ fill: 'var(--hover)' }}
              isAnimationActive={false}
              content={({ active, payload }) => {
                const b = payload?.[0]?.payload as Activity['buckets'][number] | undefined;
                if (!active || !b) return null;
                return (
                  <div className="chart-tip">
                    <span className="muted">{data.bucket === 'hour' ? fmtDateTime(b.start) : fmtDay(b.start)}</span>
                    <strong>{num(b[series])}</strong>
                  </div>
                );
              }}
            />
            <Bar dataKey={series} fill="var(--series-1)" radius={[2, 2, 0, 0]} isAnimationActive={false} />
          </BarChart>
        </ResponsiveContainer>
      </div>
    </figure>
  );
}

function MergePanel({ url }: { url: string }) {
  const state = useApi<MergedPulls>(url);
  return (
    <Card title="Time to merge" info="Merge time minus creation time, for PRs merged in the range whose creation time is known.">
      <Async state={state}>
        {(d) => {
          const t = d.duration;
          if (d.merged === 0) return <Empty>No merges observed in this range.</Empty>;
          const missing = t.excluded_unknown_created_at + t.excluded_invalid;
          return (
            <>
              <div className="stats">
                <Stat label="Median" value={t.median} />
                <Stat label="75th percentile" value={t.p75} />
                <Stat label="90th percentile" value={t.p90} />
              </div>
              <p className="sample">
                Based on <strong>{num(t.n)}</strong> of {num(d.merged)} merged PRs
                {missing > 0 && (
                  <span className="muted">
                    {' '}· {num(t.excluded_unknown_created_at)} without an observed creation time
                    {t.excluded_invalid > 0 && `, ${num(t.excluded_invalid)} with inconsistent timestamps`}
                  </span>
                )}
              </p>
              {t.n > 0 ? <DurationHistogram data={t.histogram} /> : <Empty>None of these PRs has a known creation time.</Empty>}
            </>
          );
        }}
      </Async>
    </Card>
  );
}

function Stat({ label, value }: { label: string; value: number | null }) {
  return (
    <div className="stat">
      <span className="stat-label">{label}</span>
      <span className="stat-value">{value === null ? NA : fmtDuration(value)}</span>
    </div>
  );
}

function DurationHistogram({ data }: { data: MergedPulls['duration']['histogram'] }) {
  return (
    <div className="histogram">
      <ResponsiveContainer width="100%" height="100%">
        <BarChart data={data} margin={{ top: 8, right: 4, bottom: 0, left: 0 }} barCategoryGap="18%">
          <CartesianGrid vertical={false} stroke="var(--grid)" />
          <XAxis dataKey="label" interval={0} tick={{ fill: 'var(--muted)', fontSize: 11 }} tickLine={false}
            axisLine={{ stroke: 'var(--axis)' }} height={22} />
          <YAxis allowDecimals={false} tick={{ fill: 'var(--muted)', fontSize: 11 }} tickLine={false} axisLine={false} width={34} />
          <Tooltip
            cursor={{ fill: 'var(--hover)' }}
            isAnimationActive={false}
            content={({ active, payload }) => {
              const b = payload?.[0]?.payload as { label: string; count: number } | undefined;
              if (!active || !b) return null;
              return <div className="chart-tip"><strong>{num(b.count)}</strong><span className="muted">merged in {b.label}</span></div>;
            }}
          />
          <Bar dataKey="count" fill="var(--series-1)" radius={[2, 2, 0, 0]} isAnimationActive={false} />
        </BarChart>
      </ResponsiveContainer>
    </div>
  );
}

function ContributorsPanel({ base, range }: { base: string; range: { from: string; to: string } }) {
  const [bots, setBots] = useState(false);
  const state = useApi<Contributors>(`${base}/contributors?${qs({ ...range, limit: 10, include_bots: bots })}`);
  return (
    <Card
      title="Top contributors"
      info="Ranked by push, PR, review, comment, issue and release events in the range."
      aside={
        <label className="toggle">
          <input type="checkbox" checked={bots} onChange={(e) => setBots(e.target.checked)} />
          Include bots
        </label>
      }
    >
      <Async state={state}>
        {(d) => {
          if (d.items.length === 0) return <Empty>No contributor activity in this range.</Empty>;
          const max = d.items[0]!.total;
          return (
            <>
              <ol className="contributors">
                {d.items.map((c) => (
                  <li key={c.login}>
                    <div className="contrib-row">
                      <a href={`https://github.com/${encodeURIComponent(c.login.replace(/\[bot\]$/, ''))}`} target="_blank" rel="noreferrer">
                        {c.login}
                      </a>
                      <span className="contrib-total">{num(c.total)}</span>
                    </div>
                    <span className="bar thin" style={{ width: `${(c.total / max) * 100}%` }} aria-hidden="true" />
                    <span className="muted small">{breakdown(c)}</span>
                  </li>
                ))}
              </ol>
              <p className="muted small table-foot">{num(d.total)} {bots ? 'accounts' : 'human accounts'} active in range</p>
            </>
          );
        }}
      </Async>
    </Card>
  );
}

function breakdown(c: Contributors['items'][number]) {
  const parts: [number, string][] = [
    [c.pushes, 'pushes'], [c.pull_request_events, 'PR events'], [c.reviews, 'reviews'],
    [c.comments, 'comments'], [c.issue_events, 'issue events'], [c.releases, 'releases'],
  ];
  return parts.filter(([n]) => n > 0).map(([n, l]) => `${num(n)} ${l}`).join(' · ');
}

const PR_PAGE = 25;

function OpenPrsPanel({ base, repo }: { base: string; repo: string }) {
  const [limit, setLimit] = useState(PR_PAGE);
  const state = useApi<OpenPulls>(`${base}/pulls/open?${qs({ limit })}`);
  const d = state.data;
  return (
    <Card
      title="Open pull requests (observed)"
      info="PRs whose most recent observation in the data was open; GitHub's current state may differ."
      aside={d && <p className="card-note">As of {fmtDateTime(d.as_of)}</p>}
    >
      {state.error ? <ErrorMessage error={state.error} onRetry={state.reload} /> : !d ? <Loading /> : (
        <div className={state.loading ? 'stale' : undefined}>
          <p className="state-counts">
            <span><strong>{num(d.state_counts.open)}</strong> open</span>
            <span><strong>{num(d.state_counts.merged)}</strong> merged</span>
            <span><strong>{num(d.state_counts.closed)}</strong> closed</span>
            <span>
              <strong>{num(d.state_counts.unknown)}</strong> state unknown
              <Info text="Seen only through reviews or label changes, which don't report state." />
            </span>
          </p>
          {d.items.length === 0 ? <Empty>No PRs observed as open.</Empty> : (
            <>
              <div className="table-wrap">
                <table className="table prs">
                  <thead>
                    <tr>
                      <th className="num">PR</th>
                      <th>Title</th>
                      <th>Author</th>
                      <th>Opened</th>
                      <th>Last seen<Info text="Last event of any kind that referenced the PR." /></th>
                    </tr>
                  </thead>
                  <tbody>
                    {d.items.map((p) => (
                      <tr key={p.number}>
                        <td className="num">
                          <a href={`https://github.com/${repo}/pull/${p.number}`} target="_blank" rel="noreferrer">#{p.number}</a>
                        </td>
                        <td className="title-cell">{p.title ?? <span className="muted">{NA}</span>}</td>
                        <td>{p.author ?? <span className="muted">{NA}</span>}</td>
                        <td className="nowrap">{p.created_at ? fmtDay(p.created_at) : <span className="muted">{NA}</span>}</td>
                        <td className="nowrap">{fmtDay(p.last_seen_at)}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
              <footer className="table-foot">
                <span className="muted">Showing {num(d.items.length)} of {num(d.total)}, most recently seen first</span>
                {d.items.length < d.total && limit < 500 && (
                  <button type="button" className="btn" onClick={() => setLimit((n) => Math.min(n + 100, 500))}>Show more</button>
                )}
              </footer>
            </>
          )}
        </div>
      )}
    </Card>
  );
}

import { useEffect } from 'react';
import { useApi, type Meta } from './api';
import { ErrorMessage, Loading, RangeControls, RepoSearchBox } from './components';
import { fmtDayYear, num } from './format';
import { TrendingPage } from './pages/Trending';
import { RepoDetailPage } from './pages/RepoDetail';
import { readSelection, selectionQuery } from './range';
import { Link, navigate, useLocation } from './router';

export function App() {
  const { path, search } = useLocation();
  const meta = useApi<Meta>('/api/meta');
  const repoMatch = path.match(/^\/repo\/([^/]+)\/([^/]+)\/?$/);
  const repo = repoMatch ? `${decodeURIComponent(repoMatch[1]!)}/${decodeURIComponent(repoMatch[2]!)}` : null;

  useEffect(() => {
    document.title = repo ? `${repo} · GitHub Trending` : 'GitHub Trending';
  }, [repo]);

  const cov = meta.data?.coverage;
  let body;
  if (meta.error) body = <div className="card"><ErrorMessage error={meta.error} onRetry={meta.reload} /></div>;
  else if (!meta.data) body = <div className="card"><Loading /></div>;
  else if (!cov) body = <div className="card"><p className="status">No events in the database yet. Run <code>npm run ingest</code>.</p></div>;

  const sel = cov ? readSelection(search, cov) : null;
  const rangeQuery = sel ? selectionQuery(sel) : '';
  const setRange = (query: string) => navigate(`${path}?${query}`, { scroll: false });

  return (
    <div className="app">
      <header className="topbar">
        <div className="topbar-inner">
          <Link href={`/?${rangeQuery}`} className="brand">GitHub Trending</Link>
          {meta.data && cov && (
            <span className="topbar-meta">
              {num(meta.data.totals.repos)} repositories · GH Archive events, {fmtDayYear(cov.first_event_at)} – {fmtDayYear(cov.last_event_at)}
            </span>
          )}
          {cov && <RepoSearchBox rangeQuery={rangeQuery} />}
        </div>
      </header>

      <main className="page">
        {body ?? (
          <>
            <div className="page-head">
              {repo ? (
                <div>
                  <Link href={`/?${rangeQuery}`} className="back">← Trending</Link>
                  <h1>
                    {repo}
                    <a className="ext" href={`https://github.com/${repo}`} target="_blank" rel="noreferrer">GitHub ↗</a>
                  </h1>
                </div>
              ) : (
                <div>
                  <h1>What's trending</h1>
                  <p className="muted">Repositories gaining the most stars. Select one to see what's happening inside.</p>
                </div>
              )}
              <RangeControls key={rangeQuery} sel={sel!} cov={cov!} onChange={setRange} />
            </div>
            {repo
              ? <RepoDetailPage key={repo} repo={repo} sel={sel!} rangeQuery={rangeQuery} />
              : <TrendingPage key={rangeQuery} sel={sel!} rangeQuery={rangeQuery} />}
          </>
        )}
      </main>
    </div>
  );
}

