.table .rank { width: 36px; }
.clickable { cursor: pointer; }
.clickable:hover td { background: var(--hover); }
.repo-cell a { color: var(--ink); font-weight: 500; }
.title-cell { max-width: 480px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.bar-cell { display: flex; align-items: center; justify-content: flex-end; gap: 8px; }
.bar-cell .bar { flex: none; max-width: 80px; }
.bar-cell { min-width: 130px; }
.bar { display: block; height: 6px; border-radius: 3px; background: var(--series-1); min-width: 2px; }
.bar-cell .bar { width: 0; }
.growth { display: inline-flex; flex-direction: column; align-items: flex-end; line-height: 1.25; }
.growth-pct { font-size: 11px; color: var(--muted); }
.growth.up > span:first-child { color: var(--up); }
.growth.down > span:first-child { color: var(--ink-2); }
.table-foot { display: flex; justify-content: space-between; align-items: center; gap: 12px; flex-wrap: wrap; margin: 12px 0 0; font-size: 12px; }

