import puppeteer from 'puppeteer-core';

const BASE = process.argv[2] ?? 'http://localhost:5173';
const OUT = new URL('./shots/', import.meta.url).pathname;
const log = (...a) => console.log(...a);
const problems = [];

const browser = await puppeteer.launch({
  executablePath: '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',
  headless: true,
});
const page = await browser.newPage();
page.on('console', (m) => { if (['error', 'warn'].includes(m.type())) problems.push(`console.${m.type()}: ${m.text()}`); });
page.on('pageerror', (e) => problems.push(`pageerror: ${e.message}`));
page.on('response', (r) => { if (r.url().includes('/api/') && r.status() >= 400) problems.push(`HTTP ${r.status()} ${r.url()}`); });

const text = (sel) => page.$eval(sel, (e) => e.textContent.trim());
const overflow = () => page.evaluate(() => document.documentElement.scrollWidth - window.innerWidth);
const settle = () => page.waitForNetworkIdle({ idleTime: 150 });

async function shot(name) {
  await page.screenshot({ path: `${OUT}${name}.png`, fullPage: true });
  log(`  screenshot ${name}.png  (horizontal overflow: ${await overflow()}px)`);
}

// ---- Desktop: trending
await page.setViewport({ width: 1440, height: 900 });
await page.goto(BASE + '/', { waitUntil: 'networkidle0' });
await page.waitForSelector('table.trending tbody tr');
log('[desktop] trending default:', await text('.range-label'), '| url', page.url());
const rows = await page.$$eval('table.trending tbody tr', (trs) => trs.slice(0, 3).map((tr) => [...tr.cells].map((c) => c.innerText.replace(/\s+/g, ' ').trim())));
log('  first rows:', JSON.stringify(rows));
log('  footer:', await text('.table-foot span'));
await shot('desktop-trending-7d');

for (const label of ['All', '24h', '14d']) {
  await page.evaluate((l) => [...document.querySelectorAll('.segmented button')].find((b) => b.textContent === l).click(), label);
  await settle();
