.bar-cell { display: flex; align-items: center; justify-content: flex-end; gap: 10px; }
.bar-track { flex: none; width: 72px; display: flex; justify-content: flex-end; }
.bar { display: block; height: 6px; border-radius: 3px; background: var(--series-1); min-width: 2px; }
.growth { display: inline-flex; flex-direction: column; align-items: flex-end; line-height: 1.25; }
.growth-pct { font-size: 11px; color: var(--muted); }
