.multiple-plot { height: 110px; }
.chart-tip {
  display: flex; gap: 8px; align-items: baseline; padding: 4px 8px; border-radius: 6px;
  background: #2b2b2a; border: 1px solid var(--border); font-size: 12px; white-space: nowrap;
}
.recharts-wrapper:focus, .recharts-surface:focus { outline: none; }

