rep(".table-foot { display: flex; justify-content: space-between; align-items: center; gap: 12px; flex-wrap: wrap; margin: 12px 0 0; font-size: 12px; }",
""".table-foot { margin: 10px 0 0; font-size: 12px; }
.pager {
