}
.pager-btns { display: inline-flex; gap: 6px; }
.btn:disabled { opacity: 0.4; cursor: default; }
.btn:disabled:hover { background: var(--surface-2); }""")
rep(".multiple-plot { height: 110px; }", ".multiple-plot { height: 96px; }")
rep(".recharts-wrapper:focus, .recharts-surface:focus { outline: none; }",
""".recharts-wrapper:focus, .recharts-surface:focus { outline: none; }
.inactive { display: flex; flex-wrap: wrap; align-items: baseline; gap: 4px 16px; margin: 16px 0 0; padding-top: 12px; border-top: 1px solid var(--grid); font-size: 12px; }
.inactive-item { color: var(--ink-2); }""")
rep("""/* Contributors */
.contributors { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 10px; }
.contributors li { display: flex; flex-direction: column; gap: 3px; }
.contrib-row { display: flex; justify-content: space-between; gap: 8px; }
.contrib-row a { color: var(--ink); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.contrib-total { font-variant-numeric: tabular-nums; font-weight: 600; }
.bar.thin { height: 4px; }

""", "")
rep("  .grid-2 { grid-template-columns: 1fr; }", "  .detail-row { grid-template-columns: 1fr; }")
open(p,'w').write(s)
