import { useEffect, useState } from 'react';

// Response shapes of the Express API (server/src/analytics.ts). Kept in sync by hand.

export interface Meta {
  coverage: { start: string; end: string; first_event_at: string; last_event_at: string } | null;
  totals: { events: number; repos: number; pull_requests: number };
}

export interface TrendingItem {
  rank: number;
  repo: string;
  stars: number;
  forks: number;
  prs_opened: number;
  prs_merged: number;
  contributors: number;
  previous_stars: number | null;
  stars_change: number | null;
  growth_pct: number | null;
}

export interface Trending {
  range: { from: string; to: string };
  comparison: { available: boolean; from: string; to: string; reason?: string };
  total: number;
  items: TrendingItem[];
}

export const SERIES = ['stars', 'forks', 'prs_opened', 'prs_merged', 'issues', 'reviews', 'comments', 'pushes'] as const;
export type Series = (typeof SERIES)[number];

export interface Activity {
  repo: string;
  range: { from: string; to: string };
  bucket: 'hour' | 'day';
  series: Series[];
  totals: Record<Series, number>;
  buckets: ({ start: string } & Record<Series, number>)[];
}

export interface OpenPulls {
  repo: string;
  as_of: string;
  total: number;
  state_counts: { open: number; merged: number; closed: number; unknown: number };
  items: {
    number: number;
    title: string | null;
    author: string | null;
    created_at: string | null;
    state_observed_at: string;
    last_seen_at: string;
    days_since_last_seen: number;
  }[];
}

export interface MergedPulls {
  repo: string;
  range: { from: string; to: string };
  merged: number;
  duration: {
    n: number;
    excluded_unknown_created_at: number;
    excluded_invalid: number;
    min: number | null;
    median: number | null;
    p75: number | null;
    p90: number | null;
    max: number | null;
    histogram: { label: string; count: number }[];
  };
}

export interface Contributors {
  repo: string;
  include_bots: boolean;
  total: number;
  items: {
    login: string;
    is_bot: boolean;
    total: number;
    pushes: number;
    pull_request_events: number;
    reviews: number;
    comments: number;
    issue_events: number;
    releases: number;
  }[];
}

export interface RepoSearch {
  items: { repo: string; events: number }[];
}

export class ApiError extends Error {
  constructor(public status: number, public code: string, message: string) {
    super(message);
  }
}

async function fetchJson<T>(url: string, signal: AbortSignal): Promise<T> {
  let res: Response;
  try {
    res = await fetch(url, { signal });
  } catch (e) {
    if ((e as Error).name === 'AbortError') throw e;
    throw new ApiError(0, 'network_error', 'Could not reach the API. Is the server running?');
  }
  const body = await res.json().catch(() => null);
  if (!res.ok) {
    throw new ApiError(res.status, body?.error?.code ?? 'http_error', body?.error?.message ?? `Request failed (${res.status})`);
  }
  return body as T;
}

export interface ApiState<T> {
  data: T | null;
  error: ApiError | null;
  loading: boolean;
  reload: () => void;
}

// Fetches `url` (skips when null). Keeps the previous data while a new request is in
// flight, so views dim instead of flashing empty.
export function useApi<T>(url: string | null): ApiState<T> {
  const [data, setData] = useState<T | null>(null);
  const [error, setError] = useState<ApiError | null>(null);
  const [loading, setLoading] = useState(url !== null);
  const [attempt, setAttempt] = useState(0);

  useEffect(() => {
    if (url === null) return;
    const ctrl = new AbortController();
    setLoading(true);
    fetchJson<T>(url, ctrl.signal)
      .then((d) => {
        setData(d);
        setError(null);
      })
      .catch((e) => {
        if (e.name === 'AbortError') return;
        setError(e instanceof ApiError ? e : new ApiError(0, 'unknown', String(e)));
      })
      .finally(() => {
        if (!ctrl.signal.aborted) setLoading(false);
      });
    return () => ctrl.abort();
  }, [url, attempt]);

  return { data, error, loading, reload: () => setAttempt((n) => n + 1) };
}

export const qs = (params: Record<string, string | number | boolean | undefined>) => {
  const p = new URLSearchParams();
  for (const [k, v] of Object.entries(params)) if (v !== undefined) p.set(k, String(v));
  return p.toString();
};

export const repoPath = (repo: string) => repo.split('/').map(encodeURIComponent).join('/');

import { useEffect, useState, type AnchorHTMLAttributes, type MouseEvent } from 'react';

// Two pages don't justify a routing library: pushState plus a popstate listener.

export function useLocation() {
  const read = () => ({ path: window.location.pathname, search: window.location.search });
  const [loc, setLoc] = useState(read);
  useEffect(() => {
    const onPop = () => setLoc(read());
    window.addEventListener('popstate', onPop);
    return () => window.removeEventListener('popstate', onPop);
  }, []);
  return loc;
}

export function navigate(url: string, { replace = false, scroll = true } = {}) {
  if (replace) window.history.replaceState(null, '', url);
  else window.history.pushState(null, '', url);
  window.dispatchEvent(new PopStateEvent('popstate'));
  if (scroll) window.scrollTo(0, 0);
}

// A real <a> (so middle-click, copy link, and keyboard work) that navigates in-app.
export function Link({ href, onClick, ...rest }: AnchorHTMLAttributes<HTMLAnchorElement> & { href: string }) {
  const handle = (e: MouseEvent<HTMLAnchorElement>) => {
    onClick?.(e);
    if (e.defaultPrevented || e.button !== 0 || e.metaKey || e.ctrlKey || e.shiftKey || e.altKey) return;
    e.preventDefault();
    navigate(href);
  };
  return <a href={href} onClick={handle} {...rest} />;
}

// All dates are shown in UTC, matching the API's buckets and range boundaries.

const nf = new Intl.NumberFormat('en-US');
export const num = (n: number) => nf.format(n);

const dayFmt = new Intl.DateTimeFormat('en-US', { timeZone: 'UTC', month: 'short', day: 'numeric' });
const dayYearFmt = new Intl.DateTimeFormat('en-US', { timeZone: 'UTC', month: 'short', day: 'numeric', year: 'numeric' });
const hourFmt = new Intl.DateTimeFormat('en-GB', { timeZone: 'UTC', hour: '2-digit', minute: '2-digit' });

export const fmtDay = (iso: string) => dayFmt.format(new Date(iso));
export const fmtDayYear = (iso: string) => dayYearFmt.format(new Date(iso));
export const fmtHour = (iso: string) => hourFmt.format(new Date(iso));
export const fmtDateTime = (iso: string) => `${fmtDay(iso)}, ${fmtHour(iso)} UTC`;

export const DAY_MS = 86_400_000;

// The API's `to` is exclusive; show the last included day.
export function fmtRange(from: string, to: string) {
  const last = new Date(Date.parse(to) - 1).toISOString();
  const span = Date.parse(to) - Date.parse(from);
  if (span <= DAY_MS && from.endsWith('T00:00:00Z')) return `${fmtDayYear(from)} · UTC`;
  return `${fmtDay(from)} – ${fmtDayYear(last)} · UTC`;
}

export function fmtDuration(seconds: number) {
  if (seconds < 60) return `${seconds}s`;
  if (seconds < 3600) return `${Math.round(seconds / 60)}m`;
  if (seconds < 48 * 3600) return `${(seconds / 3600).toFixed(1)}h`;
  return `${(seconds / 86400).toFixed(1)}d`;
}

export const fmtSigned = (n: number) => (n > 0 ? `+${num(n)}` : n < 0 ? `−${num(-n)}` : '0');

export const NA = 'N/A';

import { DAY_MS } from './format';

// Time range selection, stored in the URL as either `range=<preset>` or `from`/`to`
// (YYYY-MM-DD, `to` exclusive, as the API expects). Presets end at the dataset's end,
// not today's date: the data is a fixed snapshot.

export const PRESETS = [
  { key: '24h', label: '24h', days: 1 },
  { key: '7d', label: '7d', days: 7 },
  { key: '14d', label: '14d', days: 14 },
  { key: 'all', label: 'All', days: null },
] as const;
export type PresetKey = (typeof PRESETS)[number]['key'];
export const DEFAULT_PRESET: PresetKey = '7d';

export interface Coverage {
  start: string;
  end: string;
}

export interface Selection {
  preset: PresetKey | null; // null = custom
  from: string;
  to: string;
}

const day = (iso: string) => iso.slice(0, 10);
const shift = (iso: string, days: number) => new Date(Date.parse(iso) + days * DAY_MS).toISOString().replace('.000Z', 'Z');

export function presetRange(key: PresetKey, cov: Coverage) {
  const p = PRESETS.find((x) => x.key === key)!;
  return { from: p.days === null ? cov.start : shift(cov.end, -p.days), to: cov.end };
}

export function readSelection(search: string, cov: Coverage): Selection {
  const q = new URLSearchParams(search);
  const from = q.get('from');
  const to = q.get('to');
  const valid = (d: string | null) => d !== null && /^\d{4}-\d{2}-\d{2}$/.test(d) && !Number.isNaN(Date.parse(d));
  if (valid(from) && valid(to)) {
    const f = `${from}T00:00:00Z`;
    const t = `${to}T00:00:00Z`;
    if (f < t && f >= cov.start && t <= cov.end) return { preset: null, from: f, to: t };
  }
  const key = (PRESETS.find((p) => p.key === q.get('range'))?.key ?? DEFAULT_PRESET) as PresetKey;
  return { preset: key, ...presetRange(key, cov) };
}

// Query string to carry the selection across pages.
export function selectionQuery(sel: Selection): string {
  return sel.preset ? `range=${sel.preset}` : `from=${day(sel.from)}&to=${day(sel.to)}`;
}

export const toDateInput = day;
export const lastIncludedDay = (to: string) => day(shift(to, -1));
export const nextDay = (d: string) => day(shift(`${d}T00:00:00Z`, 1));

import { useEffect, useId, useRef, useState, type ReactNode } from 'react';
import { qs, repoPath, useApi, type ApiError, type RepoSearch } from './api';
import { fmtRange, num } from './format';
import { lastIncludedDay, nextDay, PRESETS, presetRange, toDateInput, type Coverage, type PresetKey, type Selection } from './range';
import { Link, navigate } from './router';

// A one-sentence explanation, shown on hover or keyboard focus.
export function Info({ text }: { text: string }) {
  const id = useId();
  return (
    <span className="info">
      <button type="button" className="info-btn" aria-describedby={id} aria-label="More information">i</button>
      <span role="tooltip" id={id} className="info-tip">{text}</span>
    </span>
  );
}

export function Card({ title, info, aside, children, className = '' }: {
  title: string; info?: string; aside?: ReactNode; children: ReactNode; className?: string;
}) {
  return (
    <section className={`card ${className}`}>
      <header className="card-head">
        <h2>{title}{info && <Info text={info} />}</h2>
        {aside}
      </header>
      {children}
    </section>
  );
}

export function Loading() {
  return <p className="status">Loading…</p>;
}

export function ErrorMessage({ error, onRetry }: { error: ApiError; onRetry?: () => void }) {
  return (
    <div className="status status-error" role="alert">
      <span>{error.message}</span>
      {onRetry && <button type="button" className="btn-link" onClick={onRetry}>Retry</button>}
    </div>
  );
}

export function Empty({ children }: { children: ReactNode }) {
  return <p className="status">{children}</p>;
}

// Renders loading / error / content for one API call. Holds stale content (dimmed)
// while a refetch is in flight.
export function Async<T>({ state, children }: {
  state: { data: T | null; error: ApiError | null; loading: boolean; reload: () => void };
  children: (data: T) => ReactNode;
}) {
  if (state.error) return <ErrorMessage error={state.error} onRetry={state.reload} />;
  if (!state.data) return <Loading />;
  return <div className={state.loading ? 'stale' : undefined} aria-busy={state.loading}>{children(state.data)}</div>;
}

export function RangeControls({ sel, cov, onChange }: {
  sel: Selection; cov: Coverage; onChange: (query: string) => void;
}) {
  const [custom, setCustom] = useState(sel.preset === null);
  const min = toDateInput(cov.start);
  const max = lastIncludedDay(cov.end);
  const start = toDateInput(sel.from);
  const end = lastIncludedDay(sel.to);

  const setCustomRange = (s: string, e: string) => {
    if (s && e && s <= e && s >= min && e <= max) onChange(`from=${s}&to=${nextDay(e)}`);
  };

  return (
    <div className="range">
      <div className="segmented" role="group" aria-label="Time range">
        {PRESETS.map((p) => (
          <button
            key={p.key}
            type="button"
            aria-pressed={!custom && sel.preset === p.key}
            onClick={() => {
              setCustom(false);
              onChange(`range=${p.key}`);
            }}
            title={rangeTitle(p.key, cov)}
          >
            {p.label}
          </button>
        ))}
        <button type="button" aria-pressed={custom} onClick={() => setCustom(true)}>Custom</button>
      </div>
      {custom ? (
        <div className="dates">
          <input type="date" aria-label="Start date (UTC)" min={min} max={max} value={start}
            onChange={(e) => setCustomRange(e.target.value, end)} />
          <span aria-hidden="true">–</span>
          <input type="date" aria-label="End date (UTC, inclusive)" min={min} max={max} value={end}
            onChange={(e) => setCustomRange(start, e.target.value)} />
          <span className="muted">UTC</span>
        </div>
      ) : (
        <span className="range-label">{fmtRange(sel.from, sel.to)}</span>
      )}
    </div>
  );
}

function rangeTitle(key: PresetKey, cov: Coverage) {
  const r = presetRange(key, cov);
  return fmtRange(r.from, r.to);
}

export function RepoSearchBox({ rangeQuery }: { rangeQuery: string }) {
  const [text, setText] = useState('');
  const [query, setQuery] = useState('');
  const [open, setOpen] = useState(false);
  const [active, setActive] = useState(0);
  const listId = useId();
  const box = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const t = setTimeout(() => setQuery(text.trim()), 150);
    return () => clearTimeout(t);
  }, [text]);
  useEffect(() => {
    const close = (e: MouseEvent) => {
      if (!box.current?.contains(e.target as Node)) setOpen(false);
    };
    document.addEventListener('mousedown', close);
    return () => document.removeEventListener('mousedown', close);
  }, []);

  const res = useApi<RepoSearch>(query ? `/api/repos?${qs({ q: query, limit: 8 })}` : null);
  const items = query && res.data ? res.data.items : [];
  const go = (repo: string) => {
    setOpen(false);
    setText('');
    navigate(`/repo/${repoPath(repo)}?${rangeQuery}`);
  };

  return (
    <div className="search" ref={box}>
      <input
        type="search"
        placeholder="Find a repository"
        aria-label="Find a repository"
        role="combobox"
        aria-expanded={open && items.length > 0}
        aria-controls={listId}
        value={text}
        onChange={(e) => {
          setText(e.target.value);
          setOpen(true);
          setActive(0);
        }}
        onFocus={() => setOpen(true)}
        onKeyDown={(e) => {
          if (e.key === 'ArrowDown') setActive((i) => Math.min(i + 1, items.length - 1));
          else if (e.key === 'ArrowUp') setActive((i) => Math.max(i - 1, 0));
          else if (e.key === 'Enter' && items[active]) go(items[active].repo);
          else if (e.key === 'Escape') setOpen(false);
          else return;
          e.preventDefault();
        }}
      />
      {open && query && (
        <ul className="search-results" id={listId} role="listbox">
          {items.map((x, i) => (
            <li key={x.repo} role="option" aria-selected={i === active}>
              <Link href={`/repo/${repoPath(x.repo)}?${rangeQuery}`} onClick={() => setOpen(false)}
                onMouseEnter={() => setActive(i)}>
                <span>{x.repo}</span>
                <span className="muted">{num(x.events)} events</span>
              </Link>
            </li>
          ))}
          {res.data && items.length === 0 && <li className="search-empty">No matching repository</li>}
        </ul>
      )}
    </div>
  );
}

import { useState } from 'react';
import { qs, repoPath, useApi, type Trending as TrendingData, type TrendingItem } from '../api';
import { Async, Card, Empty, Info } from '../components';
import { DAY_MS, fmtRange, fmtSigned, NA, num } from '../format';
import type { Selection } from '../range';
import { Link, navigate } from '../router';

const PAGE = 25;

export function TrendingPage({ sel, rangeQuery }: { sel: Selection; rangeQuery: string }) {
  const [limit, setLimit] = useState(PAGE);
  const state = useApi<TrendingData>(`/api/trending?${qs({ from: sel.from, to: sel.to, limit })}`);
  const days = Math.round((Date.parse(sel.to) - Date.parse(sel.from)) / DAY_MS);
  const windowLabel = days >= 1 ? `${days}-day` : 'equal-length';

  return (
    <Card
      title="Trending repositories"
      aside={
        <p className="card-note">
          Ranked by stars gained in {fmtRange(sel.from, sel.to)}. Growth compares with the preceding {windowLabel} window.
        </p>
      }
    >
      <Async state={state}>
        {(d) =>
          d.items.length === 0 ? (
            <Empty>No stars were observed in this range.</Empty>
          ) : (
            <>
              <TrendingTable data={d} rangeQuery={rangeQuery} />
              <footer className="table-foot">
                <span className="muted">
                  Showing {num(d.items.length)} of {num(d.total)} repositories with at least one star in range
                </span>
                {d.items.length < d.total && limit < 100 && (
                  <button type="button" className="btn" onClick={() => setLimit(100)}>
                    Show top {Math.min(100, d.total)}
                  </button>
                )}
              </footer>
            </>
          )
        }
      </Async>
    </Card>
  );
}

function TrendingTable({ data, rangeQuery }: { data: TrendingData; rangeQuery: string }) {
  const maxStars = Math.max(...data.items.map((x) => x.stars));
  return (
    <div className="table-wrap">
      <table className="table trending">
        <thead>
          <tr>
            <th className="num rank">#</th>
            <th>Repository</th>
            <th className="num">Stars<Info text="Star (WatchEvent) events observed in the range." /></th>
            <th className="num">Growth<Info text="Change in stars versus the preceding window of the same length." /></th>
            <th className="num">Forks</th>
            <th className="num">PRs opened<Info text="PRs whose creation time falls in the range, including ones seen only through comments." /></th>
            <th className="num">PRs merged</th>
            <th className="num">Contributors<Info text="Distinct non-bot accounts that pushed, opened or reviewed PRs, commented, or worked on issues." /></th>
          </tr>
        </thead>
        <tbody>
          {data.items.map((x) => {
            const href = `/repo/${repoPath(x.repo)}?${rangeQuery}`;
            return (
              <tr key={x.repo} className="clickable" onClick={(e) => {
                if ((e.target as HTMLElement).closest('a, button')) return;
                navigate(href);
              }}>
                <td className="num rank muted">{x.rank}</td>
                <td className="repo-cell"><Link href={href}>{x.repo}</Link></td>
                <td className="num">
                  <div className="bar-cell">
                    <span className="bar" style={{ width: `${(x.stars / maxStars) * 100}%` }} aria-hidden="true" />
                    <span>{num(x.stars)}</span>
                  </div>
                </td>
                <td className="num"><Growth item={x} available={data.comparison.available} /></td>
                <td className="num">{num(x.forks)}</td>
                <td className="num">{num(x.prs_opened)}</td>
                <td className="num">{num(x.prs_merged)}</td>
                <td className="num">{num(x.contributors)}</td>
              </tr>
            );
          })}
        </tbody>
      </table>
    </div>
  );
}

function Growth({ item, available }: { item: TrendingItem; available: boolean }) {
  if (!available || item.stars_change === null) {
    return <span className="muted" title="The preceding window starts before the dataset begins.">{NA}</span>;
  }
  const dir = item.stars_change > 0 ? 'up' : item.stars_change < 0 ? 'down' : 'flat';
  return (
    <span className={`growth ${dir}`} title={`${num(item.previous_stars!)} stars in the preceding window`}>
      <span>{fmtSigned(item.stars_change)}</span>
      <span className="growth-pct">
        {item.growth_pct === null ? 'new' : `${item.growth_pct > 0 ? '+' : item.growth_pct < 0 ? '−' : ''}${num(Math.abs(item.growth_pct))}%`}
      </span>
    </span>
  );
}

import { useState } from 'react';
import { Bar, BarChart, CartesianGrid, ResponsiveContainer, Tooltip, XAxis, YAxis } from 'recharts';
import {
  qs, repoPath, SERIES, useApi,
  type Activity, type Contributors, type MergedPulls, type OpenPulls, type Series,
} from '../api';
import { Async, Card, Empty, ErrorMessage, Info, Loading } from '../components';
import { fmtDateTime, fmtDay, fmtDuration, fmtHour, NA, num } from '../format';
import type { Selection } from '../range';
import { Link } from '../router';

const SERIES_INFO: Record<Series, { label: string; info: string }> = {
  stars: { label: 'Stars', info: 'Star (WatchEvent) events.' },
  forks: { label: 'Forks', info: 'Fork events.' },
  prs_opened: { label: 'PRs opened', info: 'PRs by creation time, including ones seen only through comments.' },
  prs_merged: { label: 'PRs merged', info: 'PRs by merge time.' },
  issues: { label: 'Issues opened / closed', info: 'Issues opened, closed or reopened.' },
  reviews: { label: 'Reviews', info: 'PR reviews and review comments.' },
  comments: { label: 'Comments', info: 'Comments on issues, PRs and commits.' },
  pushes: { label: 'Pushes', info: 'Push events; the data has no per-push commit counts.' },
};

export function RepoDetailPage({ repo, sel, rangeQuery }: { repo: string; sel: Selection; rangeQuery: string }) {
  const base = `/api/repos/${repoPath(repo)}`;
  const range = { from: sel.from, to: sel.to };
  const activity = useApi<Activity>(`${base}/activity?${qs(range)}`);

  // Every panel 404s together for an unknown repo; show one page-level message.
  if (activity.error?.code === 'repo_not_found') {
    return (
      <div className="card">
        <ErrorMessage error={activity.error} />
        <p className="status"><Link href={`/?${rangeQuery}`}>Back to trending</Link></p>
      </div>
    );
  }

  return (
    <>
      <ActivityPanel state={activity} />
      <div className="grid-2">
        <MergePanel url={`${base}/pulls/merged?${qs({ ...range, limit: 1 })}`} />
        <ContributorsPanel base={base} range={range} />
      </div>
      <OpenPrsPanel base={base} repo={repo} />
    </>
  );
}

function ActivityPanel({ state }: { state: ReturnType<typeof useApi<Activity>> }) {
  return (
    <Card
      title="Activity over time"
      aside={state.data && <p className="card-note">{state.data.bucket === 'hour' ? 'Hourly' : 'Daily'} UTC buckets · each chart has its own scale</p>}
    >
      <Async state={state}>
        {(d) => (
          <div className="multiples">
            {SERIES.map((s) => <SeriesChart key={s} data={d} series={s} />)}
          </div>
        )}
      </Async>
    </Card>
  );
}

function SeriesChart({ data, series }: { data: Activity; series: Series }) {
  const { label, info } = SERIES_INFO[series];
  const max = Math.max(...data.buckets.map((b) => b[series]));
  const fmtTick = data.bucket === 'hour' ? fmtHour : fmtDay;
  const first = data.buckets[0]?.start;
  const last = data.buckets.at(-1)?.start;
  return (
    <figure className="multiple">
      <figcaption>
        <span className="multiple-label">{label}<Info text={info} /></span>
        <span className="multiple-total">{num(data.totals[series])}</span>
      </figcaption>
      <div className="multiple-plot">
        <ResponsiveContainer width="100%" height="100%">
          <BarChart data={data.buckets} margin={{ top: 4, right: 4, bottom: 0, left: 0 }} barCategoryGap="12%">
            <CartesianGrid vertical={false} stroke="var(--grid)" />
            <XAxis
              dataKey="start"
              ticks={first && last && first !== last ? [first, last] : first ? [first] : []}
              interval={0}
              tickFormatter={fmtTick}
              tick={{ fill: 'var(--muted)', fontSize: 11 }}
              tickLine={false}
              axisLine={{ stroke: 'var(--axis)' }}
              height={20}
            />
            <YAxis
              domain={[0, Math.max(max, 1)]}
              ticks={max > 0 ? [0, max] : [0]}
              allowDecimals={false}
              tickFormatter={(v: number) => num(v)}
              tick={{ fill: 'var(--muted)', fontSize: 11 }}
              tickLine={false}
              axisLine={false}
              width={34}
            />
            <Tooltip
              cursor={{ fill: 'var(--hover)' }}
              isAnimationActive={false}
              content={({ active, payload }) => {
                const b = payload?.[0]?.payload as Activity['buckets'][number] | undefined;
                if (!active || !b) return null;
                return (
                  <div className="chart-tip">
                    <span className="muted">{data.bucket === 'hour' ? fmtDateTime(b.start) : fmtDay(b.start)}</span>
                    <strong>{num(b[series])}</strong>
                  </div>
                );
              }}
            />
            <Bar dataKey={series} fill="var(--series-1)" radius={[2, 2, 0, 0]} isAnimationActive={false} />
          </BarChart>
        </ResponsiveContainer>
      </div>
    </figure>
  );
}

function MergePanel({ url }: { url: string }) {
  const state = useApi<MergedPulls>(url);
  return (
    <Card title="Time to merge" info="Merge time minus creation time, for PRs merged in the range whose creation time is known.">
      <Async state={state}>
        {(d) => {
          const t = d.duration;
          if (d.merged === 0) return <Empty>No merges observed in this range.</Empty>;
          const missing = t.excluded_unknown_created_at + t.excluded_invalid;
          return (
            <>
              <div className="stats">
                <Stat label="Median" value={t.median} />
                <Stat label="75th percentile" value={t.p75} />
                <Stat label="90th percentile" value={t.p90} />
              </div>
              <p className="sample">
                Based on <strong>{num(t.n)}</strong> of {num(d.merged)} merged PRs
                {missing > 0 && (
                  <span className="muted">
                    {' '}· {num(t.excluded_unknown_created_at)} without an observed creation time
                    {t.excluded_invalid > 0 && `, ${num(t.excluded_invalid)} with inconsistent timestamps`}
                  </span>
                )}
              </p>
              {t.n > 0 ? <DurationHistogram data={t.histogram} /> : <Empty>None of these PRs has a known creation time.</Empty>}
            </>
          );
        }}
      </Async>
    </Card>
  );
}

function Stat({ label, value }: { label: string; value: number | null }) {
  return (
    <div className="stat">
      <span className="stat-label">{label}</span>
      <span className="stat-value">{value === null ? NA : fmtDuration(value)}</span>
    </div>
  );
}

function DurationHistogram({ data }: { data: MergedPulls['duration']['histogram'] }) {
  return (
    <div className="histogram">
      <ResponsiveContainer width="100%" height="100%">
        <BarChart data={data} margin={{ top: 8, right: 4, bottom: 0, left: 0 }} barCategoryGap="18%">
          <CartesianGrid vertical={false} stroke="var(--grid)" />
          <XAxis dataKey="label" interval={0} tick={{ fill: 'var(--muted)', fontSize: 11 }} tickLine={false}
            axisLine={{ stroke: 'var(--axis)' }} height={22} />
          <YAxis allowDecimals={false} tick={{ fill: 'var(--muted)', fontSize: 11 }} tickLine={false} axisLine={false} width={34} />
          <Tooltip
            cursor={{ fill: 'var(--hover)' }}
            isAnimationActive={false}
            content={({ active, payload }) => {
              const b = payload?.[0]?.payload as { label: string; count: number } | undefined;
              if (!active || !b) return null;
              return <div className="chart-tip"><strong>{num(b.count)}</strong><span className="muted">merged in {b.label}</span></div>;
            }}
          />
          <Bar dataKey="count" fill="var(--series-1)" radius={[2, 2, 0, 0]} isAnimationActive={false} />
        </BarChart>
      </ResponsiveContainer>
    </div>
  );
}

function ContributorsPanel({ base, range }: { base: string; range: { from: string; to: string } }) {
  const [bots, setBots] = useState(false);
  const state = useApi<Contributors>(`${base}/contributors?${qs({ ...range, limit: 10, include_bots: bots })}`);
  return (
    <Card
      title="Top contributors"
      info="Ranked by push, PR, review, comment, issue and release events in the range."
      aside={
        <label className="toggle">
          <input type="checkbox" checked={bots} onChange={(e) => setBots(e.target.checked)} />
          Include bots
        </label>
      }
    >
      <Async state={state}>
        {(d) => {
          if (d.items.length === 0) return <Empty>No contributor activity in this range.</Empty>;
          const max = d.items[0]!.total;
          return (
            <>
              <ol className="contributors">
                {d.items.map((c) => (
                  <li key={c.login}>
                    <div className="contrib-row">
                      <a href={`https://github.com/${encodeURIComponent(c.login.replace(/\[bot\]$/, ''))}`} target="_blank" rel="noreferrer">
                        {c.login}
                      </a>
                      <span className="contrib-total">{num(c.total)}</span>
                    </div>
                    <span className="bar thin" style={{ width: `${(c.total / max) * 100}%` }} aria-hidden="true" />
                    <span className="muted small">{breakdown(c)}</span>
                  </li>
                ))}
              </ol>
              <p className="muted small table-foot">{num(d.total)} {bots ? 'accounts' : 'human accounts'} active in range</p>
            </>
          );
        }}
      </Async>
    </Card>
  );
}

function breakdown(c: Contributors['items'][number]) {
  const parts: [number, string][] = [
    [c.pushes, 'pushes'], [c.pull_request_events, 'PR events'], [c.reviews, 'reviews'],
    [c.comments, 'comments'], [c.issue_events, 'issue events'], [c.releases, 'releases'],
  ];
  return parts.filter(([n]) => n > 0).map(([n, l]) => `${num(n)} ${l}`).join(' · ');
}

const PR_PAGE = 25;

function OpenPrsPanel({ base, repo }: { base: string; repo: string }) {
  const [limit, setLimit] = useState(PR_PAGE);
  const state = useApi<OpenPulls>(`${base}/pulls/open?${qs({ limit })}`);
  const d = state.data;
  return (
    <Card
      title="Open pull requests (observed)"
      info="PRs whose most recent observation in the data was open; GitHub's current state may differ."
      aside={d && <p className="card-note">As of {fmtDateTime(d.as_of)}</p>}
    >
      {state.error ? <ErrorMessage error={state.error} onRetry={state.reload} /> : !d ? <Loading /> : (
        <div className={state.loading ? 'stale' : undefined}>
          <p className="state-counts">
            <span><strong>{num(d.state_counts.open)}</strong> open</span>
            <span><strong>{num(d.state_counts.merged)}</strong> merged</span>
            <span><strong>{num(d.state_counts.closed)}</strong> closed</span>
            <span>
              <strong>{num(d.state_counts.unknown)}</strong> state unknown
              <Info text="Seen only through reviews or label changes, which don't report state." />
            </span>
          </p>
          {d.items.length === 0 ? <Empty>No PRs observed as open.</Empty> : (
            <>
              <div className="table-wrap">
                <table className="table prs">
                  <thead>
                    <tr>
                      <th className="num">PR</th>
                      <th>Title</th>
                      <th>Author</th>
                      <th>Opened</th>
                      <th>Last seen<Info text="Last event of any kind that referenced the PR." /></th>
                    </tr>
                  </thead>
                  <tbody>
                    {d.items.map((p) => (
                      <tr key={p.number}>
                        <td className="num">
                          <a href={`https://github.com/${repo}/pull/${p.number}`} target="_blank" rel="noreferrer">#{p.number}</a>
                        </td>
                        <td className="title-cell">{p.title ?? <span className="muted">{NA}</span>}</td>
                        <td>{p.author ?? <span className="muted">{NA}</span>}</td>
                        <td className="nowrap">{p.created_at ? fmtDay(p.created_at) : <span className="muted">{NA}</span>}</td>
                        <td className="nowrap">{fmtDay(p.last_seen_at)}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
              <footer className="table-foot">
                <span className="muted">Showing {num(d.items.length)} of {num(d.total)}, most recently seen first</span>
                {d.items.length < d.total && limit < 500 && (
                  <button type="button" className="btn" onClick={() => setLimit((n) => Math.min(n + 100, 500))}>Show more</button>
                )}
              </footer>
            </>
          )}
        </div>
      )}
    </Card>
  );
}

import { useEffect } from 'react';
import { useApi, type Meta } from './api';
import { ErrorMessage, Loading, RangeControls, RepoSearchBox } from './components';
import { fmtDayYear, num } from './format';
import { TrendingPage } from './pages/Trending';
import { RepoDetailPage } from './pages/RepoDetail';
import { readSelection, selectionQuery } from './range';
import { Link, navigate, useLocation } from './router';

export function App() {
  const { path, search } = useLocation();
  const meta = useApi<Meta>('/api/meta');
  const repoMatch = path.match(/^\/repo\/([^/]+)\/([^/]+)\/?$/);
  const repo = repoMatch ? `${decodeURIComponent(repoMatch[1]!)}/${decodeURIComponent(repoMatch[2]!)}` : null;

  useEffect(() => {
    document.title = repo ? `${repo} · GitHub Trending` : 'GitHub Trending';
  }, [repo]);

  const cov = meta.data?.coverage;
  let body;
  if (meta.error) body = <div className="card"><ErrorMessage error={meta.error} onRetry={meta.reload} /></div>;
  else if (!meta.data) body = <div className="card"><Loading /></div>;
  else if (!cov) body = <div className="card"><p className="status">No events in the database yet. Run <code>npm run ingest</code>.</p></div>;

  const sel = cov ? readSelection(search, cov) : null;
  const rangeQuery = sel ? selectionQuery(sel) : '';
  const setRange = (query: string) => navigate(`${path}?${query}`, { scroll: false });

  return (
    <div className="app">
      <header className="topbar">
        <div className="topbar-inner">
          <Link href={`/?${rangeQuery}`} className="brand">GitHub Trending</Link>
          {meta.data && cov && (
            <span className="topbar-meta">
              {num(meta.data.totals.repos)} repositories · GH Archive events, {fmtDayYear(cov.first_event_at)} – {fmtDayYear(cov.last_event_at)}
            </span>
          )}
          {cov && <RepoSearchBox rangeQuery={rangeQuery} />}
        </div>
      </header>

      <main className="page">
        {body ?? (
          <>
            <div className="page-head">
              {repo ? (
                <div>
                  <Link href={`/?${rangeQuery}`} className="back">← Trending</Link>
                  <h1>
                    {repo}
                    <a className="ext" href={`https://github.com/${repo}`} target="_blank" rel="noreferrer">GitHub ↗</a>
                  </h1>
                </div>
              ) : (
                <div>
                  <h1>What's trending</h1>
                  <p className="muted">Repositories gaining the most stars. Select one to see what's happening inside.</p>
                </div>
              )}
              <RangeControls key={rangeQuery} sel={sel!} cov={cov!} onChange={setRange} />
            </div>
            {repo
              ? <RepoDetailPage key={repo} repo={repo} sel={sel!} rangeQuery={rangeQuery} />
              : <TrendingPage key={rangeQuery} sel={sel!} rangeQuery={rangeQuery} />}
          </>
        )}
      </main>
    </div>
  );
}

import { StrictMode } from 'react';
import { createRoot } from 'react-dom/client';
import { App } from './App';
import './styles.css';

createRoot(document.getElementById('root')!).render(
  <StrictMode>
    <App />
  </StrictMode>,
);

/* Single dark theme. Chart colors come from the validated dark palette:
   one series hue (slot 1), recessive hairline grid and axes. */
:root {
  color-scheme: dark;
  --page: #0d0d0d;
  --surface: #1a1a19;
  --surface-2: #232322;
  --border: rgba(255, 255, 255, 0.1);
  --ink: #f0efec;
  --ink-2: #c3c2b7;
  --muted: #898781;
  --grid: #2c2c2a;
  --axis: #383835;
  --hover: rgba(255, 255, 255, 0.06);
  --series-1: #3987e5;
  --link: #6da7ec;
  --up: #0ca30c;
  --critical: #e66767;
  --radius: 10px;
  --font: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --mono: ui-monospace, SFMono-Regular, Menlo, monospace;
}

* { box-sizing: border-box; }
html, body { margin: 0; }
body {
  background: var(--page);
  color: var(--ink);
  font: 14px/1.5 var(--font);
  -webkit-font-smoothing: antialiased;
}
a { color: var(--link); text-decoration: none; }
a:hover { text-decoration: underline; }
a:focus-visible, button:focus-visible, input:focus-visible {
  outline: 2px solid var(--series-1);
  outline-offset: 2px;
}
h1, h2 { margin: 0; font-weight: 600; }
h1 { font-size: 22px; letter-spacing: -0.01em; }
h2 { font-size: 14px; }
code { font-family: var(--mono); font-size: 13px; }
.muted { color: var(--muted); }
.small { font-size: 12px; }
.nowrap { white-space: nowrap; }

/* Layout */
.topbar { border-bottom: 1px solid var(--border); background: var(--surface); }
.topbar-inner, .page { max-width: 1200px; margin: 0 auto; padding: 0 24px; }
.topbar-inner { display: flex; align-items: center; gap: 16px; min-height: 56px; flex-wrap: wrap; }
.brand { color: var(--ink); font-weight: 600; font-size: 15px; }
.brand:hover { text-decoration: none; }
.topbar-meta { color: var(--muted); font-size: 12px; }
.page { padding-top: 24px; padding-bottom: 48px; display: flex; flex-direction: column; gap: 16px; }
.page-head { display: flex; justify-content: space-between; align-items: flex-end; gap: 16px; flex-wrap: wrap; }
.page-head p { margin: 4px 0 0; }
.back { font-size: 13px; color: var(--muted); }
.ext { font-size: 12px; font-weight: 400; margin-left: 12px; }
.grid-2 { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }

/* Cards */
.card { background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius); padding: 16px 20px; min-width: 0; }
.card-head { display: flex; justify-content: space-between; align-items: baseline; gap: 12px; flex-wrap: wrap; margin-bottom: 12px; }
.card-note { margin: 0; color: var(--muted); font-size: 12px; }
.status { color: var(--muted); margin: 0; padding: 24px 0; text-align: center; }
.status-error { color: var(--critical); display: flex; gap: 12px; justify-content: center; align-items: center; }
.stale { opacity: 0.55; transition: opacity 0.15s; }

/* Controls */
.range { display: flex; align-items: center; gap: 12px; flex-wrap: wrap; }
.range-label, .dates { color: var(--ink-2); font-size: 13px; }
.dates { display: flex; align-items: center; gap: 6px; }
.segmented { display: inline-flex; background: var(--surface); border: 1px solid var(--border); border-radius: 8px; padding: 2px; }
.segmented button {
  background: none; border: 0; color: var(--ink-2); font: inherit; font-size: 13px;
  padding: 4px 12px; border-radius: 6px; cursor: pointer;
}
.segmented button:hover { background: var(--hover); }
.segmented button[aria-pressed="true"] { background: var(--surface-2); color: var(--ink); box-shadow: inset 0 0 0 1px var(--border); }
input[type="date"], input[type="search"] {
  background: var(--page); color: var(--ink); border: 1px solid var(--border); border-radius: 6px;
  font: inherit; font-size: 13px; padding: 5px 8px;
}
.btn {
  background: var(--surface-2); color: var(--ink); border: 1px solid var(--border); border-radius: 6px;
  font: inherit; font-size: 13px; padding: 4px 12px; cursor: pointer;
}
.btn:hover { background: #2b2b2a; }
.btn-link { background: none; border: 0; color: var(--link); font: inherit; cursor: pointer; padding: 0; }
.toggle { display: inline-flex; align-items: center; gap: 6px; color: var(--ink-2); font-size: 12px; cursor: pointer; }

/* Search */
.search { position: relative; margin-left: auto; width: 260px; }
.search input { width: 100%; }
.search-results {
  position: absolute; z-index: 20; top: calc(100% + 4px); left: 0; right: 0; margin: 0; padding: 4px;
  list-style: none; background: var(--surface-2); border: 1px solid var(--border); border-radius: 8px;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
}
.search-results a { display: flex; justify-content: space-between; gap: 8px; padding: 6px 8px; border-radius: 6px; color: var(--ink); font-size: 13px; }
.search-results a span:first-child { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.search-results a span:last-child { flex-shrink: 0; font-size: 12px; }
.search-results li[aria-selected="true"] a { background: var(--hover); text-decoration: none; }
.search-empty { padding: 6px 8px; color: var(--muted); font-size: 13px; }

/* Info tooltip */
.info { position: relative; display: inline-flex; vertical-align: middle; margin-left: 4px; }
.info-btn {
  width: 14px; height: 14px; border-radius: 50%; border: 1px solid var(--muted); background: none;
  color: var(--muted); font: 600 9px/1 var(--font); padding: 0; cursor: help;
  display: inline-flex; align-items: center; justify-content: center;
}
.info-tip {
  position: absolute; z-index: 30; bottom: calc(100% + 6px); left: 50%; transform: translateX(-50%);
  width: max-content; max-width: 240px; padding: 6px 8px; border-radius: 6px;
  background: #2b2b2a; border: 1px solid var(--border); color: var(--ink); text-align: left;
  font-size: 12px; font-weight: 400; line-height: 1.4; white-space: normal; text-transform: none; letter-spacing: 0;
  pointer-events: none; opacity: 0; visibility: hidden; transition: opacity 0.1s;
}
.info:hover .info-tip, .info-btn:focus-visible + .info-tip { opacity: 1; visibility: visible; }

/* Tables */
.table-wrap { overflow-x: auto; margin: 0 -20px; padding: 0 20px; }
.table { width: 100%; border-collapse: collapse; font-variant-numeric: tabular-nums; }
.table th {
  text-align: left; font-weight: 500; font-size: 12px; color: var(--muted);
  padding: 8px 10px; border-bottom: 1px solid var(--border); white-space: nowrap;
}
.table td { padding: 9px 10px; border-bottom: 1px solid var(--grid); vertical-align: middle; }
.table tbody tr:last-child td { border-bottom: 0; }
.table .num { text-align: right; }
.table th.num .info-tip { left: auto; right: -8px; transform: none; }
.table .rank { width: 36px; }
.clickable { cursor: pointer; }
.clickable:hover td { background: var(--hover); }
.repo-cell a { color: var(--ink); font-weight: 500; }
.title-cell { max-width: 480px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.bar-cell { display: flex; align-items: center; justify-content: flex-end; gap: 8px; }
.bar-cell .bar { flex: none; max-width: 80px; }
.bar-cell { min-width: 130px; }
.bar { display: block; height: 6px; border-radius: 3px; background: var(--series-1); min-width: 2px; }
.bar-cell .bar { width: 0; }
.growth { display: inline-flex; flex-direction: column; align-items: flex-end; line-height: 1.25; }
.growth-pct { font-size: 11px; color: var(--muted); }
.growth.up > span:first-child { color: var(--up); }
.growth.down > span:first-child { color: var(--ink-2); }
.table-foot { display: flex; justify-content: space-between; align-items: center; gap: 12px; flex-wrap: wrap; margin: 12px 0 0; font-size: 12px; }

/* Activity small multiples */
.multiples { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 20px 24px; }
.multiple { margin: 0; min-width: 0; }
.multiple figcaption { display: flex; justify-content: space-between; align-items: baseline; gap: 8px; margin-bottom: 4px; }
.multiple-label { color: var(--ink-2); font-size: 12px; }
.multiple-total { font-size: 16px; font-weight: 600; }
.multiple-plot { height: 110px; }
.chart-tip {
  display: flex; gap: 8px; align-items: baseline; padding: 4px 8px; border-radius: 6px;
  background: #2b2b2a; border: 1px solid var(--border); font-size: 12px; white-space: nowrap;
}
.recharts-wrapper:focus, .recharts-surface:focus { outline: none; }

/* Merge stats */
.stats { display: grid; grid-template-columns: repeat(3, 1fr); gap: 12px; }
.stat { display: flex; flex-direction: column; background: var(--page); border: 1px solid var(--border); border-radius: 8px; padding: 10px 12px; }
.stat-label { color: var(--muted); font-size: 12px; }
.stat-value { font-size: 22px; font-weight: 600; }
.sample { margin: 12px 0 8px; font-size: 13px; color: var(--ink-2); }
.histogram { height: 170px; }

/* Contributors */
.contributors { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 10px; }
.contributors li { display: flex; flex-direction: column; gap: 3px; }
.contrib-row { display: flex; justify-content: space-between; gap: 8px; }
.contrib-row a { color: var(--ink); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.contrib-total { font-variant-numeric: tabular-nums; font-weight: 600; }
.bar.thin { height: 4px; }

/* PR state counts */
.state-counts { display: flex; flex-wrap: wrap; gap: 6px 20px; margin: 0 0 8px; color: var(--ink-2); font-size: 13px; }
.state-counts strong { color: var(--ink); }

@media (max-width: 960px) {
  .multiples { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .grid-2 { grid-template-columns: 1fr; }
}
@media (max-width: 640px) {
  .topbar-inner, .page { padding-left: 16px; padding-right: 16px; }
  .topbar-inner { padding-top: 10px; padding-bottom: 10px; }
  .topbar-meta { display: none; }
  .search { width: 100%; margin-left: 0; }
  .card { padding: 14px 16px; }
  .table-wrap { margin: 0 -16px; padding: 0 16px; }
  .multiples { grid-template-columns: 1fr; }
  .stat-value { font-size: 18px; }
  .stats { gap: 8px; }
  h1 { font-size: 19px; word-break: break-word; }
}

