input.content:
import puppeteer from 'puppeteer-core';

const BASE = process.argv[2] ?? 'http://localhost:5173';
const OUT = new URL('./shots/', import.meta.url).pathname;
const log = (...a) => console.log(...a);
const problems = [];

const browser = await puppeteer.launch({
  executablePath: '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',
  headless: true,
});
const page = await browser.newPage();
page.on('console', (m) => { if (['error', 'warn'].includes(m.type())) problems.push(`console.${m.type()}: ${m.text()}`); });
page.on('pageerror', (e) => problems.push(`pageerror: ${e.message}`));
page.on('response', (r) => { if (r.url().includes('/api/') && r.status() >= 400) problems.push(`HTTP ${r.status()} ${r.url()}`); });

const text = (sel) => page.$eval(sel, (e) => e.textContent.trim());
const overflow = () => page.evaluate(() => document.documentElement.scrollWidth - window.innerWidth);
const settle = () => page.waitForNetworkIdle({ idleTime: 150 });

async function shot(name) {
  await page.screenshot({ path: `${OUT}${name}.png`, fullPage: true });
  log(`  screenshot ${name}.png  (horizontal overflow: ${await overflow()}px)`);
}

// ---- Desktop: trending
await page.setViewport({ width: 1440, height: 900 });
await page.goto(BASE + '/', { waitUntil: 'networkidle0' });
await page.waitForSelector('table.trending tbody tr');
log('[desktop] trending default:', await text('.range-label'), '| url', page.url());
const rows = await page.$$eval('table.trending tbody tr', (trs) => trs.slice(0, 3).map((tr) => [...tr.cells].map((c) => c.innerText.replace(/\s+/g, ' ').trim())));
log('  first rows:', JSON.stringify(rows));
log('  footer:', await text('.table-foot span'));
await shot('desktop-trending-7d');

for (const label of ['All', '24h', '14d']) {
  await page.evaluate((l) => [...document.querySelectorAll('.segmented button')].find((b) => b.textContent === l).click(), label);
  await settle();
  const growth = await page.$$eval('table.trending tbody tr td:nth-child(4)', (tds) => tds.slice(0, 3).map((t) => t.innerText.replace(/\s+/g, ' ')));
  log(`  preset ${label}: url=${new URL(page.url()).search} label="${await text('.range-label')}" growth=${JSON.stringify(growth)}`);
}
await page.evaluate(() => [...document.querySelectorAll('.segmented button')].find((b) => b.textContent === 'All').click());
await settle();
await shot('desktop-trending-all');

// Show more
await page.evaluate(() => [...document.querySelectorAll('.table-foot button')][0]?.click());
await settle();
log('  after "Show top": rows =', await page.$$eval('table.trending tbody tr', (t) => t.length), '|', await text('.table-foot span'));

// Custom range
await page.evaluate(() => [...document.querySelectorAll('.segmented button')].find((b) => b.textContent === 'Custom').click());
const setDate = async (idx, v) => {
  await page.evaluate((i, val) => {
    const el = document.querySelectorAll('.dates input')[i];
    const setter = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'value').set;
    setter.call(el, val);
    el.dispatchEvent(new Event('input', { bubbles: true }));
  }, idx, v);
  await settle();
};
await setDate(0, '2026-08-10');
await setDate(1, '2026-08-16');
log('  custom range url:', new URL(page.url()).search, '| note:', await text('.card-note'));

// Row click (on a non-link cell) navigates to detail
await page.click('table.trending tbody tr:first-child td:nth-child(5)');
await page.waitForSelector('.multiples .recharts-bar-rectangle, .multiples .recharts-bar', { timeout: 10000 });
await settle();
log('[desktop] detail via row click:', new URL(page.url()).pathname + new URL(page.url()).search, '| h1:', await text('h1'));
log('  range kept:', await page.$eval('.dates input', (e) => e.value).catch(() => 'n/a'));

// Detail of a busy repo, 7d
await page.goto(BASE + '/repo/openclaw/openclaw?range=7d', { waitUntil: 'networkidle0' });
await page.waitForSelector('.multiples svg');
log('[desktop] openclaw 7d');
log('  multiples:', JSON.stringify(await page.$$eval('.multiple figcaption', (f) => f.map((x) => x.innerText.replace(/\s+/g, ' ')))));
log('  bucket note:', await text('.card-note'));
log('  merge stats:', JSON.stringify(await page.$$eval('.stat', (s) => s.map((x) => x.innerText.replace(/\s+/g, ' ')))), '|', await text('.sample'));
log('  contributors first:', await text('.contributors li'), '| foot:', await page.$$eval('.grid-2 .table-foot', (f) => f.map((x) => x.innerText).join()));
log('  pr counts:', await text('.state-counts'));
log('  pr first row:', await page.$eval('table.prs tbody tr', (tr) => tr.innerText.replace(/\s+/g, ' ')));
const naCount = await page.$$eval('table.prs tbody td', (tds) => tds.filter((t) => t.innerText === 'N/A').length);
log('  N/A cells in open-PR table:', naCount);

// Hover a bar -> tooltip
const bar = await page.$('.multiple:nth-child(8) .recharts-bar-rectangle:last-child path, .multiple:nth-child(8) .recharts-rectangle');
if (bar) {
  const box = await bar.boundingBox();
  await page.mouse.move(box.x + box.width / 2, box.y + box.height / 2);
  await page.waitForSelector('.chart-tip', { timeout: 3000 }).catch(() => {});
  log('  tooltip on hover:', await page.$eval('.chart-tip', (e) => e.innerText.replace(/\s+/g, ' ')).catch(() => 'NONE'));
} else problems.push('no bar found to hover');
await shot('desktop-detail-openclaw-7d');

// Include bots toggle
const before = await page.$$eval('.contributors li a', (a) => a.map((x) => x.textContent));
await page.click('.toggle input');
await settle();
const after = await page.$$eval('.contributors li a', (a) => a.map((x) => x.textContent));
log('  bots toggle: before', before.slice(0, 3), 'after', after.slice(0, 3), '| foot:', await page.$$eval('.grid-2 .table-foot', (f) => f.map((x) => x.innerText).join()));

// Open PRs show more
const n0 = await page.$$eval('table.prs tbody tr', (t) => t.length);
await page.evaluate(() => [...document.querySelectorAll('.card .table-foot button')].at(-1)?.click());
await settle();
log('  open PRs rows:', n0, '->', await page.$$eval('table.prs tbody tr', (t) => t.length));

// Hourly view
await page.goto(BASE + '/repo/openclaw/openclaw?range=24h', { waitUntil: 'networkidle0' });
await page.waitForSelector('.multiples svg');
log('[desktop] 24h bucket note:', await text('.card-note'), '| x ticks:', JSON.stringify(await page.$$eval('.multiple:first-child .recharts-xAxis .recharts-cartesian-axis-tick', (t) => t.map((x) => x.textContent))));

// Repo with little activity: find the quietest via search API
const quiet = await page.evaluate(async () => (await (await fetch('/api/trending?limit=100')).json()).items.at(-1).repo);
await page.goto(`${BASE}/repo/${quiet}?range=24h`, { waitUntil: 'networkidle0' });
await page.waitForSelector('.multiples svg');
log(`[desktop] quiet repo ${quiet} 24h: statuses=`, JSON.stringify(await page.$$eval('.status', (s) => s.map((x) => x.innerText))));
await shot('desktop-detail-quiet-24h');

// Search
await page.goto(BASE + '/?range=7d', { waitUntil: 'networkidle0' });
await page.type('.search input', 'posthog');
await page.waitForSelector('.search-results li[role="option"]');
log('[desktop] search results:', JSON.stringify(await page.$$eval('.search-results li', (l) => l.map((x) => x.innerText.replace(/\s+/g, ' ')))));
await page.keyboard.press('Enter');
await page.waitForSelector('.multiples svg');
log('  enter ->', new URL(page.url()).pathname + new URL(page.url()).search);
await page.goBack();
await page.waitForSelector('table.trending');
log('  back ->', new URL(page.url()).pathname + new URL(page.url()).search);
await page.type('.search input', 'zzzz-nothing');
await page.waitForSelector('.search-empty');
log('  no-match:', await text('.search-empty'));

// Unknown repo and bad URL params
await page.goto(BASE + '/repo/no/such-repo', { waitUntil: 'networkidle0' });
await page.waitForSelector('.status-error');
log('[desktop] unknown repo:', await text('.status-error'));
await page.goto(BASE + '/?from=2025-01-01&to=2025-02-01', { waitUntil: 'networkidle0' });
log('  out-of-coverage URL falls back to:', await text('.range-label'));

// ---- Mobile
await page.setViewport({ width: 390, height: 844, deviceScaleFactor: 2, isMobile: true, hasTouch: true });
await page.goto(BASE + '/?range=7d', { waitUntil: 'networkidle0' });
await page.waitForSelector('table.trending');
log('[mobile]');
await shot('mobile-trending');
await page.goto(BASE + '/repo/openclaw/openclaw?range=7d', { waitUntil: 'networkidle0' });
await page.waitForSelector('.multiples svg');
await settle();
await shot('mobile-detail');
await page.setViewport({ width: 820, height: 1000 });
await page.reload({ waitUntil: 'networkidle0' });
await page.waitForSelector('.multiples svg');
await shot('tablet-detail');

await browser.close();
log('\nproblems:', problems.length ? problems : 'none');

