import type { ReactNode } from 'react';

// Shared Recharts styling: recessive axes and grid, and one compact tooltip style.

export const AXIS_TICK = { fill: 'var(--muted)', fontSize: 11 } as const;

// Spread onto <Tooltip>: may rise above the plot (small charts are short) but never
// past its sides, sits above neighbouring charts, and doesn't animate.
export const TOOLTIP_PROPS = {
  allowEscapeViewBox: { x: false, y: true },
  wrapperStyle: { zIndex: 5, outline: 'none', pointerEvents: 'none' as const },
  offset: 10,
  isAnimationActive: false,
  cursor: { fill: 'var(--hover)' },
};

export function ChartTip({ value, label }: { value: ReactNode; label: ReactNode }) {
  return (
    <div className="chart-tip">
      <strong>{value}</strong>
      <span className="muted">{label}</span>
    </div>
  );
}

import { Bar, BarChart, CartesianGrid, ResponsiveContainer, Tooltip, XAxis, YAxis, type XAxisTickContentProps } from 'recharts';
import { SERIES, type Activity, type ApiState, type Series } from '../api';
import { fmtDay, fmtHour, num } from '../format';
import { Async, Card, Empty, Info } from '../ui';
import { AXIS_TICK, ChartTip, TOOLTIP_PROPS } from './chart';

const SERIES_INFO: Record<Series, { label: string; unit: string; info: string }> = {
  stars: { label: 'Stars', unit: 'stars', info: 'Star (WatchEvent) events.' },
  forks: { label: 'Forks', unit: 'forks', info: 'Fork events.' },
  prs_opened: { label: 'PRs opened', unit: 'PRs opened', info: 'PRs by creation time, including ones seen only through comments.' },
  prs_merged: { label: 'PRs merged', unit: 'PRs merged', info: 'PRs by merge time.' },
  issues: { label: 'Issues', unit: 'issue events', info: 'Issues opened, closed or reopened.' },
  reviews: { label: 'Reviews', unit: 'reviews', info: 'PR reviews and review comments.' },
  comments: { label: 'Comments', unit: 'comments', info: 'Comments on issues, PRs and commits.' },
  pushes: { label: 'Pushes', unit: 'pushes', info: 'Push events; the data has no per-push commit counts.' },
};

// One small chart per active series (each on its own scale). Series with no activity in
// the whole range are listed compactly with their zero total instead of an empty chart.
export function ActivitySection({ state }: { state: ApiState<Activity> }) {
  return (
    <Card
      title="Activity over time"
      aside={state.data && (
        <p className="card-note">{state.data.bucket === 'hour' ? 'Hourly' : 'Daily'} UTC buckets · each chart has its own scale</p>
      )}
    >
      <Async state={state}>
        {(d) => {
          const active = SERIES.filter((s) => d.totals[s] > 0);
          const inactive = SERIES.filter((s) => d.totals[s] === 0);
          if (active.length === 0) return <Empty>No activity in this range.</Empty>;
          return (
            <>
              <div className="multiples">
                {active.map((s) => <SeriesChart key={s} data={d} series={s} />)}
              </div>
              {inactive.length > 0 && (
                <p className="inactive">
                  <span className="muted">No activity in this range:</span>
                  {inactive.map((s) => (
                    <span key={s} className="inactive-item">{SERIES_INFO[s].label} <strong>0</strong></span>
                  ))}
                </p>
              )}
            </>
          );
        }}
      </Async>
    </Card>
  );
}

function SeriesChart({ data, series }: { data: Activity; series: Series }) {
  const { label, unit, info } = SERIES_INFO[series];
  const max = Math.max(...data.buckets.map((b) => b[series]));
  const hourly = data.bucket === 'hour';
  const fmtTick = hourly ? (iso: string) => `${fmtDay(iso)} ${fmtHour(iso)}` : fmtDay;
  const first = data.buckets[0]?.start;
  const last = data.buckets.at(-1)?.start;
  return (
    <figure className="multiple">
      <figcaption>
        <span className="multiple-label">{label}<Info text={info} /></span>
        <span className="multiple-total">{num(data.totals[series])}</span>
      </figcaption>
      <div className="multiple-plot">
        <ResponsiveContainer width="100%" height="100%">
          <BarChart data={data.buckets} margin={{ top: 4, right: 4, bottom: 0, left: 0 }} barCategoryGap="12%">
            <CartesianGrid vertical={false} stroke="var(--grid)" />
            <XAxis
              dataKey="start"
              ticks={first && last && first !== last ? [first, last] : first ? [first] : []}
              interval={0}
              // Only the first and last bucket are labelled; anchor them inward so they never clip.
              tick={(p: XAxisTickContentProps) => (
                <text x={p.x} y={Number(p.y) + 12} textAnchor={p.index === 0 ? 'start' : 'end'} {...AXIS_TICK}>
                  {fmtTick(p.payload.value)}
                </text>
              )}
              tickLine={false}
              axisLine={{ stroke: 'var(--axis)' }}
              height={20}
            />
            <YAxis domain={[0, max]} ticks={[0, max]} allowDecimals={false} tickFormatter={(v: number) => num(v)}
              tick={AXIS_TICK} tickLine={false} axisLine={false} width={34} />
            <Tooltip
              {...TOOLTIP_PROPS}
              content={({ active, payload }) => {
                const b = payload?.[0]?.payload as Activity['buckets'][number] | undefined;
                if (!active || !b) return null;
                return <ChartTip value={num(b[series])} label={`${unit} · ${hourly ? `${fmtDay(b.start)} ${fmtHour(b.start)} UTC` : fmtDay(b.start)}`} />;
              }}
            />
            <Bar dataKey={series} fill="var(--series-1)" radius={[2, 2, 0, 0]} isAnimationActive={false} />
          </BarChart>
        </ResponsiveContainer>
      </div>
    </figure>
  );
}

import { Bar, BarChart, CartesianGrid, ResponsiveContainer, Tooltip, XAxis, YAxis } from 'recharts';
import { useApi, type MergedPulls } from '../api';
import { fmtDuration, NA, num } from '../format';
import { Async, Card, Empty } from '../ui';
import { AXIS_TICK, ChartTip, TOOLTIP_PROPS } from './chart';

export function MergeDurationSection({ url }: { url: string }) {
  const state = useApi<MergedPulls>(url);
  return (
    <Card title="Time to merge" info="Merge time minus creation time, for PRs merged in the range whose creation time is known.">
      <Async state={state}>
        {(d) => {
          const t = d.duration;
          if (d.merged === 0) return <Empty>No merges observed in this range.</Empty>;
          return (
            <>
              <div className="stats">
                <Stat label="Median" value={t.median} />
                <Stat label="75th pct." value={t.p75} />
                <Stat label="90th pct." value={t.p90} />
              </div>
              <p className="sample">
                Based on <strong>{num(t.n)}</strong> of {num(d.merged)} merged PRs
                {t.excluded_unknown_created_at > 0 && (
                  <span className="muted"> · {num(t.excluded_unknown_created_at)} without an observed creation time</span>
                )}
                {t.excluded_invalid > 0 && <span className="muted"> · {num(t.excluded_invalid)} with inconsistent timestamps</span>}
              </p>
              {t.n > 0 ? <Histogram data={t.histogram} /> : <Empty>None of these PRs has a known creation time.</Empty>}
            </>
          );
        }}
      </Async>
    </Card>
  );
}

function Stat({ label, value }: { label: string; value: number | null }) {
  return (
    <div className="stat">
      <span className="stat-label">{label}</span>
      <span className="stat-value">{value === null ? NA : fmtDuration(value)}</span>
    </div>
  );
}

function Histogram({ data }: { data: MergedPulls['duration']['histogram'] }) {
  return (
    <div className="histogram">
      <ResponsiveContainer width="100%" height="100%">
        <BarChart data={data} margin={{ top: 8, right: 4, bottom: 0, left: 0 }} barCategoryGap="18%">
          <CartesianGrid vertical={false} stroke="var(--grid)" />
          <XAxis dataKey="label" interval={0} tick={AXIS_TICK} tickLine={false} axisLine={{ stroke: 'var(--axis)' }} height={22} />
          <YAxis allowDecimals={false} tick={AXIS_TICK} tickLine={false} axisLine={false} width={34} />
          <Tooltip
            {...TOOLTIP_PROPS}
            content={({ active, payload }) => {
              const b = payload?.[0]?.payload as { label: string; count: number } | undefined;
              if (!active || !b) return null;
              return <ChartTip value={num(b.count)} label={`merged in ${b.label}`} />;
            }}
          />
          <Bar dataKey="count" fill="var(--series-1)" radius={[2, 2, 0, 0]} isAnimationActive={false} />
        </BarChart>
      </ResponsiveContainer>
    </div>
  );
}

import { useState } from 'react';
import { qs, useApi, type Contributors } from '../api';
import { num } from '../format';
import { Async, Card, Empty, Info } from '../ui';

export function ContributorsSection({ base, range }: { base: string; range: { from: string; to: string } }) {
  const [bots, setBots] = useState(false);
  const state = useApi<Contributors>(`${base}/contributors?${qs({ ...range, limit: 10, include_bots: bots })}`);
  return (
    <Card
      title="Top contributors"
      info="The 10 most active accounts by push, PR, review, comment, issue and release events."
      aside={
        <label className="toggle">
          <input type="checkbox" checked={bots} onChange={(e) => setBots(e.target.checked)} />
          Include bots
        </label>
      }
    >
      <Async state={state}>
        {(d) => d.items.length === 0 ? <Empty>No contributor activity in this range.</Empty> : (
          <>
            <div className="table-wrap">
              <table className="table compact contributors">
                <thead>
                  <tr>
                    <th>Account</th>
                    <th className="num">Pushes</th>
                    <th className="num">PR events</th>
                    <th className="num">Reviews</th>
                    <th className="num">Comments</th>
                    <th className="num">Issue events</th>
                    <th className="num">Total<Info text="All counted events, including releases." /></th>
                  </tr>
                </thead>
                <tbody>
                  {d.items.map((c) => (
                    <tr key={c.login}>
                      <td className="login-cell">
                        <a href={`https://github.com/${encodeURIComponent(c.login.replace(/\[bot\]$/, ''))}`} target="_blank" rel="noreferrer">
                          {c.login}
                        </a>
                      </td>
                      <Count n={c.pushes} />
                      <Count n={c.pull_request_events} />
                      <Count n={c.reviews} />
                      <Count n={c.comments} />
                      <Count n={c.issue_events} />
                      <td className="num"><strong>{num(c.total)}</strong></td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
            <p className="table-foot muted">{num(d.total)} {bots ? 'accounts' : 'human accounts'} active in range</p>
          </>
        )}
      </Async>
    </Card>
  );
}

// Zeros are real counts; they're dimmed so the non-zero activity stands out.
function Count({ n }: { n: number }) {
  return <td className={`num${n === 0 ? ' muted' : ''}`}>{num(n)}</td>;
}

import { useRef, useState } from 'react';
import { qs, useApi, type OpenPulls } from '../api';
import { fmtDateTime, fmtDay, NA, num } from '../format';
import { Card, Empty, ErrorMessage, Info, Loading, Pager, scrollIntoViewIfAbove } from '../ui';

const PAGE_SIZE = 25;

// Not range-filtered: this is the latest observed state as of the end of the data.
// The parent remounts this per repository, which resets the page.
export function OpenPullRequestsSection({ base, repo }: { base: string; repo: string }) {
  const card = useRef<HTMLElement>(null);
  const [offset, setOffset] = useState(0);
  const state = useApi<OpenPulls>(`${base}/pulls/open?${qs({ limit: PAGE_SIZE, offset })}`);
  const d = state.data;

  return (
    <Card
      cardRef={card}
      title="Open pull requests (observed)"
      info="PRs whose most recent observation in the data was open; GitHub's current state may differ."
      aside={d && <p className="card-note">As of {fmtDateTime(d.as_of)}</p>}
    >
      {state.error ? <ErrorMessage error={state.error} onRetry={state.reload} /> : !d ? <Loading /> : (
        <div className={state.loading ? 'stale' : undefined} aria-busy={state.loading}>
          <p className="state-counts">
            <span><strong>{num(d.state_counts.open)}</strong> open</span>
            <span><strong>{num(d.state_counts.merged)}</strong> merged</span>
            <span><strong>{num(d.state_counts.closed)}</strong> closed</span>
            <span>
              <strong>{num(d.state_counts.unknown)}</strong> state unknown
              <Info text="Seen only through reviews or label changes, which don't report state." />
            </span>
          </p>
          {d.total === 0 ? <Empty>No PRs observed as open.</Empty> : (
            <div className="table-wrap">
              <table className="table compact prs">
                <thead>
                  <tr>
                    <th className="num">PR</th>
                    <th>Title</th>
                    <th>Author</th>
                    <th>Opened</th>
                    <th>Last seen<Info text="Last event of any kind that referenced the PR." /></th>
                  </tr>
                </thead>
                <tbody>
                  {d.items.map((p) => (
                    <tr key={p.number}>
                      <td className="num">
                        <a href={`https://github.com/${repo}/pull/${p.number}`} target="_blank" rel="noreferrer">#{p.number}</a>
                      </td>
                      <td className="title-cell">{p.title ?? <span className="muted">{NA}</span>}</td>
                      <td>{p.author ?? <span className="muted">{NA}</span>}</td>
                      <td className="nowrap">{p.created_at ? fmtDay(p.created_at) : <span className="muted">{NA}</span>}</td>
                      <td className="nowrap">{fmtDay(p.last_seen_at)}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
          <Pager offset={d.offset} limit={d.limit} total={d.total} noun="open PRs" onChange={(o) => {
            setOffset(o);
            scrollIntoViewIfAbove(card.current);
          }} />
        </div>
      )}
    </Card>
  );
}

import { qs, repoPath, useApi, type Activity } from '../api';
import type { Selection } from '../range';
import { Link } from '../router';
import { ErrorMessage } from '../ui';
import { ActivitySection } from './Activity';
import { ContributorsSection } from './Contributors';
import { MergeDurationSection } from './MergeDuration';
import { OpenPullRequestsSection } from './OpenPullRequests';

export function RepoDetailPage({ repo, sel, rangeQuery }: { repo: string; sel: Selection; rangeQuery: string }) {
  const base = `/api/repos/${repoPath(repo)}`;
  const range = { from: sel.from, to: sel.to };
  const activity = useApi<Activity>(`${base}/activity?${qs(range)}`);

  // Every section 404s together for an unknown repo; show one page-level message.
  if (activity.error?.code === 'repo_not_found') {
    return (
      <div className="card">
        <ErrorMessage error={activity.error} />
        <p className="status"><Link href={`/?${rangeQuery}`}>Back to trending</Link></p>
      </div>
    );
  }

  return (
    <>
      <ActivitySection state={activity} />
      <div className="detail-row">
        <MergeDurationSection url={`${base}/pulls/merged?${qs({ ...range, limit: 1 })}`} />
        <ContributorsSection base={base} range={range} />
      </div>
      <OpenPullRequestsSection base={base} repo={repo} />
    </>
  );
}

